    if(itype == rocblas_eform_ax || itype == rocblas_eform_abx)  // itype 1 or 2
    {
        // Use TRSM: solve op(B)*X = A for X (overwrites A)
        if(uplo == rocblas_fill_upper)
            // Solve U*X = A  =>  X = U^(-1)*A
            rocsolver_trsm_upper<BATCHED, STRIDED, T>(
